// MaxEco Node E.2: Load Business Registers from Local Storage
const fs = require('fs');
const path = require('path');

const testDataPath = path.resolve(process.cwd(), 'automation/data/dummy-finance-registers.json');
let data = {};

if (fs.existsSync(testDataPath)) {
  data = JSON.parse(fs.readFileSync(testDataPath, 'utf8'));
} else {
  data = {
    invoices: [],
    expenses: [],
    drawings: [],
    quotations: [],
    solarProjects: [],
    itProjects: []
  };
}

return [{ json: data }];

// MaxEco Node E.3: Strict Cash-Basis Accounting Engine
// Enforces strict separation of billed invoices, collected cash, tax reserve, and drawings

const raw = $input.first().json;
const invoices = raw.invoices || [];
const expenses = raw.expenses || [];
const drawings = raw.drawings || [];
const quotations = raw.quotations || [];

// 1. Quoted Pipeline (Not revenue)
const quotedPipelineTotal = quotations.reduce((sum, q) => sum + (Number(q.totalAmount) || 0), 0);

// 2. Invoiced vs Collected Cash
let totalBilled = 0;
let realCollectedCash = 0;
let outstandingReceivables = 0;
const overdueInvoices = [];

const todayStr = new Date().toISOString().slice(0, 10);

invoices.forEach(inv => {
  const billed = Number(inv.amountBilled) || 0;
  const collected = Number(inv.amountCollected) || 0;
  totalBilled += billed;
  realCollectedCash += collected;

  const unpaid = billed - collected;
  if (unpaid > 0) {
    outstandingReceivables += unpaid;
    if (inv.dueDate && inv.dueDate < todayStr) {
      overdueInvoices.push({
        id: inv.id,
        clientName: inv.clientName,
        amountDue: unpaid,
        dueDate: inv.dueDate
      });
    }
  }
});

// 3. Direct Delivery Costs vs Operating Overheads
let directProjectCosts = 0;
let operatingOverheads = 0;
expenses.forEach(exp => {
  const amt = Number(exp.amount) || 0;
  if (exp.category === 'Direct Delivery Cost' || exp.linkedProject) {
    directProjectCosts += amt;
  } else {
    operatingOverheads += amt;
  }
});

// 4. Gross Profit on Real Cash
const grossProfitCash = realCollectedCash - directProjectCosts;

// 5. 18% Tax / GST Reserve on collected cash
const taxReserveRate = (raw.taxReserveRatePercent || 18) / 100;
const taxReserveAllocated = Math.round(realCollectedCash * taxReserveRate);

// 6. Founder Personal Living Drawings (Isolated)
const founderDrawings = drawings.reduce((sum, d) => sum + (Number(d.amount) || 0), 0);

// 7. Net Cash Balance (True liquid runway)
const netAvailableCash = realCollectedCash - directProjectCosts - operatingOverheads - founderDrawings - taxReserveAllocated;

return [{
  json: {
    ...raw,
    metrics: {
      quotedPipelineTotal,
      totalBilled,
      realCollectedCash,
      outstandingReceivables,
      overdueInvoices,
      directProjectCosts,
      operatingOverheads,
      grossProfitCash,
      taxReserveAllocated,
      founderDrawings,
      netAvailableCash
    }
  }
}];

// MaxEco Node E.4: Projects & Milestone Pipeline Rollup
const data = $input.first().json;
const solarProjects = data.solarProjects || [];
const itProjects = data.itProjects || [];

let totalSolarMilestones = 0;
let completedSolarMilestones = 0;
let pendingSolarMilestones = 0;

solarProjects.forEach(p => {
  (p.milestones || []).forEach(m => {
    totalSolarMilestones++;
    if (m.status === 'Completed') completedSolarMilestones++;
    else pendingSolarMilestones++;
  });
});

let totalItMilestones = 0;
let completedItMilestones = 0;
let pendingItMilestones = 0;

itProjects.forEach(p => {
  (p.milestones || []).forEach(m => {
    totalItMilestones++;
    if (m.status === 'Completed') completedItMilestones++;
    else pendingItMilestones++;
  });
});

return [{
  json: {
    ...data,
    milestoneSummary: {
      solar: { total: totalSolarMilestones, completed: completedSolarMilestones, pending: pendingSolarMilestones },
      it: { total: totalItMilestones, completed: completedItMilestones, pending: pendingItMilestones }
    }
  }
}];

// MaxEco Node E.6: Save Local Management Report to Disk & Audit Output
const fs = require('fs');
const path = require('path');

const payload = $input.first().json;
const outDir = path.resolve(process.cwd(), 'docs/reports');
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

const reportFilePath = path.join(outDir, `weekly-management-report-${payload.reportDate}.md`);
fs.writeFileSync(reportFilePath, payload.reportMarkdown, 'utf8');

return [{
  json: {
    status: 'SUCCESS',
    reportDate: payload.reportDate,
    savedTo: reportFilePath,
    netAvailableCash: payload.metrics.netAvailableCash,
    outstandingReceivables: payload.metrics.outstandingReceivables,
    overdueInvoiceCount: payload.metrics.overdueInvoices.length,
    completedAt: new Date().toISOString()
  }
}];
